            movaps  xmm2, [esi]
            movaps  xmm3, [edx]
            mulps   xmm2, xmm0
            mulps   xmm3, xmm1
            addps   xmm2, xmm3
            movaps  [eax], xmm2
            add     eax, outStride
            add     esi, fromStride
            add     edx, toStride
            dec     ecx
            jne     next
        done:
