    void SetPosition(const C3DVector& p) { this->X = p.X; this->Y = p.Y; this->Z = p.Z; }
    void SetNormal(const C3DVector& p) { this->NormalX = p.X; this->NormalY = p.Y; this->NormalZ = p.Z; }
